#!/usr/bin/env node
// Conventional commit message check — runs in the commit-msg hook.
// Format: <type>(<scope>): <subject>

import { readFileSync } from 'node:fs';

const messageFile = process.argv[2];
const raw = readFileSync(messageFile, 'utf8');
const firstLine =
  raw
    .split('\n')
    .find((l) => l.trim() && !l.startsWith('#'))
    ?.trim() ?? '';

// Merge/Revert/fixup! commits are generated by git/tools — always allowed.
if (
  !firstLine ||
  firstLine.startsWith('Merge') ||
  firstLine.startsWith('Revert') ||
  /^(fixup|squash|amend)!/i.test(firstLine)
)
  process.exit(0);

const CONVENTIONAL =
  /^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-z0-9-]+\))?!?: .+$/;

if (!CONVENTIONAL.test(firstLine)) {
  console.error(`✗ Invalid commit message: "${firstLine}"`);
  console.error('  Use conventional format: <type>(<scope>): <subject>');
  console.error(
    '  types: feat | fix | docs | style | refactor | perf | test | build | ci | chore | revert'
  );
  console.error('  example: feat(compensation-event): add list page');
  process.exit(1);
}
if (firstLine.length > 72) {
  console.error(`✗ Commit subject exceeds 72 characters (${firstLine.length}).`);
  process.exit(1);
}
